/* 380 hubv 폐쇄대장 — 허브 폐쇄말소대장 위의 '우리 폐쇄 표 모양' 뷰 (hub_views_closed.py 가 만든다 · 손으로 고치지 말 것) */
IF SCHEMA_ID('hubv') IS NULL EXEC('CREATE SCHEMA hubv');
GO
CREATE OR ALTER VIEW hubv.bld_closed_title AS
SELECT CAST(NULLIF(LTRIM(RTRIM([관리_폐쇄말소대장_PK])), N'') AS VARCHAR(30)) AS [mgm_shtreg_pk],
       CAST(NULLIF(LTRIM(RTRIM([폐쇄말소_구분_코드])), N'') AS VARCHAR(2)) AS [shter_gb_cd],
       CAST(NULLIF(LTRIM(RTRIM([폐쇄말소_구분_코드_명])), N'') AS NVARCHAR(20)) AS [shter_gb_nm],
       CAST(CASE WHEN NULLIF(LTRIM(RTRIM([폐쇄말소_일])), N'') LIKE N'[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' THEN NULLIF(LTRIM(RTRIM([폐쇄말소_일])), N'') END AS CHAR(8)) AS [shter_day],
       CAST(NULLIF(LTRIM(RTRIM([대장_구분_코드_명])), N'') AS NVARCHAR(20)) AS [regstr_gb_nm],
       CAST(NULLIF(LTRIM(RTRIM([대장_종류_코드_명])), N'') AS NVARCHAR(20)) AS [regstr_kind_nm],
       CAST(NULLIF(LTRIM(RTRIM([시군구_코드])), N'') AS CHAR(5)) AS [sigungu_cd],
       CAST(NULLIF(LTRIM(RTRIM([법정동_코드])), N'') AS CHAR(5)) AS [bjdong_cd],
       CAST(NULLIF(LTRIM(RTRIM([대지_구분_코드])), N'') AS VARCHAR(1)) AS [plat_gb_cd],
       CAST(NULLIF(LTRIM(RTRIM([번])), N'') AS VARCHAR(10)) AS [bun],
       CAST(NULLIF(LTRIM(RTRIM([지])), N'') AS VARCHAR(10)) AS [ji],
       CASE WHEN LEN(NULLIF(LTRIM(RTRIM([시군구_코드])), N'')) = 5 AND LEN(NULLIF(LTRIM(RTRIM([법정동_코드])), N'')) = 5 AND (NULLIF(LTRIM(RTRIM([번])), N'') IS NULL OR TRY_CAST(NULLIF(LTRIM(RTRIM([번])), N'') AS INT) IS NOT NULL) AND (NULLIF(LTRIM(RTRIM([지])), N'') IS NULL OR TRY_CAST(NULLIF(LTRIM(RTRIM([지])), N'') AS INT) IS NOT NULL) THEN CAST(NULLIF(LTRIM(RTRIM([시군구_코드])), N'') + NULLIF(LTRIM(RTRIM([법정동_코드])), N'') + CASE LTRIM(RTRIM(ISNULL([대지_구분_코드], N'0'))) WHEN N'1' THEN N'2' ELSE N'1' END + RIGHT(N'0000' + CAST(ISNULL(TRY_CAST(NULLIF(LTRIM(RTRIM([번])), N'') AS INT), 0) AS NVARCHAR(10)), 4) + RIGHT(N'0000' + CAST(ISNULL(TRY_CAST(NULLIF(LTRIM(RTRIM([지])), N'') AS INT), 0) AS NVARCHAR(10)), 4) AS CHAR(19)) END AS [pnu],
       CAST(NULLIF(LTRIM(RTRIM([대지_위치])), N'') AS NVARCHAR(300)) AS [plat_plc],
       CAST(NULLIF(LTRIM(RTRIM([도로명_대지_위치])), N'') AS NVARCHAR(300)) AS [new_plat_plc],
       CAST(NULLIF(LTRIM(RTRIM([건물_명])), N'') AS NVARCHAR(200)) AS [bld_nm],
       CAST(NULLIF(LTRIM(RTRIM([동_명])), N'') AS NVARCHAR(100)) AS [dong_nm],
       CAST(NULLIF(LTRIM(RTRIM([주_부속_구분_코드_명])), N'') AS NVARCHAR(20)) AS [main_atch_gb_nm],
       CAST(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([대지_면적])), N''), N',', N'')), 0) AS DECIMAL(19, 5)) AS [plat_area],
       CAST(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([건축_면적])), N''), N',', N'')), 0) AS DECIMAL(19, 5)) AS [arch_area],
       CAST(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([건폐_율])), N''), N',', N'')), 0) AS DECIMAL(19, 5)) AS [bc_rat],
       CAST(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([연면적])), N''), N',', N'')), 0) AS DECIMAL(19, 5)) AS [tot_area],
       CAST(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([용적_률])), N''), N',', N'')), 0) AS DECIMAL(19, 5)) AS [vl_rat],
       CAST(NULLIF(LTRIM(RTRIM([구조_코드_명])), N'') AS NVARCHAR(100)) AS [strct_nm],
       CAST(NULLIF(LTRIM(RTRIM([주_용도_코드])), N'') AS VARCHAR(10)) AS [main_purps_cd],
       CAST(NULLIF(LTRIM(RTRIM([주_용도_코드_명])), N'') AS NVARCHAR(100)) AS [main_purps_nm],
       CAST(NULLIF(LTRIM(RTRIM([기타_용도])), N'') AS NVARCHAR(400)) AS [etc_purps],
       CAST(ROUND(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([세대_수])), N''), N',', N'')), 0), 0) AS INT) AS [hhld_cnt],
       CAST(ROUND(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([가구_수])), N''), N',', N'')), 0), 0) AS INT) AS [fmly_cnt],
       CAST(ROUND(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([호_수])), N''), N',', N'')), 0), 0) AS INT) AS [ho_cnt],
       CAST(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([높이])), N''), N',', N'')), 0) AS DECIMAL(19, 3)) AS [heit],
       CAST(ROUND(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([지상_층_수])), N''), N',', N'')), 0), 0) AS INT) AS [grnd_flr_cnt],
       CAST(ROUND(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([지하_층_수])), N''), N',', N'')), 0), 0) AS INT) AS [ugrnd_flr_cnt],
       CAST(CASE WHEN NULLIF(LTRIM(RTRIM([사용승인_일])), N'') LIKE N'[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' THEN NULLIF(LTRIM(RTRIM([사용승인_일])), N'') END AS CHAR(8)) AS [use_apr_day],
       CAST(CASE WHEN NULLIF(LTRIM(RTRIM([허가_일])), N'') LIKE N'[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' THEN NULLIF(LTRIM(RTRIM([허가_일])), N'') END AS CHAR(8)) AS [pms_day],
       CAST(CASE WHEN NULLIF(LTRIM(RTRIM([착공_일])), N'') LIKE N'[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' THEN NULLIF(LTRIM(RTRIM([착공_일])), N'') END AS CHAR(8)) AS [stcns_day],
       CAST(CASE WHEN NULLIF(LTRIM(RTRIM([생성_일자])), N'') LIKE N'[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' THEN NULLIF(LTRIM(RTRIM([생성_일자])), N'') END AS CHAR(8)) AS [crtn_day],
       CAST(SYSDATETIME() AS DATETIME2(0)) AS [loaded_at]
  FROM hub.t0403
 WHERE [마지막월] IS NULL AND NULLIF(LTRIM(RTRIM([관리_폐쇄말소대장_PK])), N'') IS NOT NULL;
GO
CREATE OR ALTER VIEW hubv.bld_closed_recap AS
SELECT CAST(NULLIF(LTRIM(RTRIM([관리_폐쇄말소대장_PK])), N'') AS VARCHAR(30)) AS [mgm_shtreg_pk],
       CAST(NULLIF(LTRIM(RTRIM([폐쇄말소_구분_코드])), N'') AS VARCHAR(2)) AS [shter_gb_cd],
       CAST(NULLIF(LTRIM(RTRIM([폐쇄말소_구분_코드_명])), N'') AS NVARCHAR(20)) AS [shter_gb_nm],
       CAST(CASE WHEN NULLIF(LTRIM(RTRIM([폐쇄말소_일])), N'') LIKE N'[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' THEN NULLIF(LTRIM(RTRIM([폐쇄말소_일])), N'') END AS CHAR(8)) AS [shter_day],
       CAST(NULLIF(LTRIM(RTRIM([대장_구분_코드_명])), N'') AS NVARCHAR(20)) AS [regstr_gb_nm],
       CAST(NULLIF(LTRIM(RTRIM([신_구_대장_구분_코드_명])), N'') AS NVARCHAR(20)) AS [new_old_regstr_gb_nm],
       CAST(NULLIF(LTRIM(RTRIM([시군구_코드])), N'') AS CHAR(5)) AS [sigungu_cd],
       CAST(NULLIF(LTRIM(RTRIM([법정동_코드])), N'') AS CHAR(5)) AS [bjdong_cd],
       CAST(NULLIF(LTRIM(RTRIM([대지_구분_코드])), N'') AS VARCHAR(1)) AS [plat_gb_cd],
       CAST(NULLIF(LTRIM(RTRIM([번])), N'') AS VARCHAR(10)) AS [bun],
       CAST(NULLIF(LTRIM(RTRIM([지])), N'') AS VARCHAR(10)) AS [ji],
       CASE WHEN LEN(NULLIF(LTRIM(RTRIM([시군구_코드])), N'')) = 5 AND LEN(NULLIF(LTRIM(RTRIM([법정동_코드])), N'')) = 5 AND (NULLIF(LTRIM(RTRIM([번])), N'') IS NULL OR TRY_CAST(NULLIF(LTRIM(RTRIM([번])), N'') AS INT) IS NOT NULL) AND (NULLIF(LTRIM(RTRIM([지])), N'') IS NULL OR TRY_CAST(NULLIF(LTRIM(RTRIM([지])), N'') AS INT) IS NOT NULL) THEN CAST(NULLIF(LTRIM(RTRIM([시군구_코드])), N'') + NULLIF(LTRIM(RTRIM([법정동_코드])), N'') + CASE LTRIM(RTRIM(ISNULL([대지_구분_코드], N'0'))) WHEN N'1' THEN N'2' ELSE N'1' END + RIGHT(N'0000' + CAST(ISNULL(TRY_CAST(NULLIF(LTRIM(RTRIM([번])), N'') AS INT), 0) AS NVARCHAR(10)), 4) + RIGHT(N'0000' + CAST(ISNULL(TRY_CAST(NULLIF(LTRIM(RTRIM([지])), N'') AS INT), 0) AS NVARCHAR(10)), 4) AS CHAR(19)) END AS [pnu],
       CAST(NULLIF(LTRIM(RTRIM([대지_위치])), N'') AS NVARCHAR(300)) AS [plat_plc],
       CAST(NULLIF(LTRIM(RTRIM([도로명_대지_위치])), N'') AS NVARCHAR(300)) AS [new_plat_plc],
       CAST(NULLIF(LTRIM(RTRIM([건물_명])), N'') AS NVARCHAR(200)) AS [bld_nm],
       CAST(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([대지_면적])), N''), N',', N'')), 0) AS DECIMAL(19, 5)) AS [plat_area],
       CAST(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([건축_면적])), N''), N',', N'')), 0) AS DECIMAL(19, 5)) AS [arch_area],
       CAST(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([건폐_율])), N''), N',', N'')), 0) AS DECIMAL(19, 5)) AS [bc_rat],
       CAST(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([연면적])), N''), N',', N'')), 0) AS DECIMAL(19, 5)) AS [tot_area],
       CAST(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([용적_률])), N''), N',', N'')), 0) AS DECIMAL(19, 5)) AS [vl_rat],
       CAST(NULLIF(LTRIM(RTRIM([주_용도_코드_명])), N'') AS NVARCHAR(100)) AS [main_purps_nm],
       CAST(ROUND(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([주_건축물_수])), N''), N',', N'')), 0), 0) AS INT) AS [main_bld_cnt],
       CAST(ROUND(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([부속_건축물_수])), N''), N',', N'')), 0), 0) AS INT) AS [atch_bld_cnt],
       CAST(ROUND(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([세대_수])), N''), N',', N'')), 0), 0) AS INT) AS [hhld_cnt],
       CAST(ROUND(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([가구_수])), N''), N',', N'')), 0), 0) AS INT) AS [fmly_cnt],
       CAST(ROUND(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([호_수])), N''), N',', N'')), 0), 0) AS INT) AS [ho_cnt],
       CAST(ROUND(NULLIF(TRY_CONVERT(FLOAT, REPLACE(NULLIF(LTRIM(RTRIM([총_주차_수])), N''), N',', N'')), 0), 0) AS INT) AS [tot_pkng_cnt],
       CAST(CASE WHEN NULLIF(LTRIM(RTRIM([사용승인_일])), N'') LIKE N'[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' THEN NULLIF(LTRIM(RTRIM([사용승인_일])), N'') END AS CHAR(8)) AS [use_apr_day],
       CAST(CASE WHEN NULLIF(LTRIM(RTRIM([허가_일])), N'') LIKE N'[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' THEN NULLIF(LTRIM(RTRIM([허가_일])), N'') END AS CHAR(8)) AS [pms_day],
       CAST(CASE WHEN NULLIF(LTRIM(RTRIM([생성_일자])), N'') LIKE N'[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' THEN NULLIF(LTRIM(RTRIM([생성_일자])), N'') END AS CHAR(8)) AS [crtn_day],
       CAST(SYSDATETIME() AS DATETIME2(0)) AS [loaded_at]
  FROM hub.t0402
 WHERE [마지막월] IS NULL AND NULLIF(LTRIM(RTRIM([관리_폐쇄말소대장_PK])), N'') IS NOT NULL;
GO

